import { z } from 'zod';

/**
 * Blast radius contracts — the wire shape of `GET /pulls/:id/blast`.
 *
 * Every node and edge here is READ OUT OF THE INDEX (symbols / references /
 * file_edges / file_facts / file_rank), never generated by a model. `summary`
 * is a deterministic sentence built from the counts, not an LLM paraphrase —
 * so the whole payload is reproducible from the same index state.
 *
 * Distinct from `BlastRadius` in contracts/brief.ts: that one is the *brief*'s
 * LLM-facing block and stays as-is. This one is the API/UI/MCP shape and adds
 * the two things a reviewer needs to trust it — per-symbol truncation counts
 * and an explicit index `status`.
 */

/**
 * How much of this answer the index could actually support. NEVER collapse
 * `degraded` into an empty `symbols` array: "we don't know" and "nothing is
 * affected" are opposite answers for a reviewer.
 *
 *  - `ready`    — index is `full`; the map is complete to the limits below.
 *  - `partial`  — index is `partial` (parse timeouts / size caps / soft budget);
 *                 what is here is true, but callers may be missing.
 *  - `degraded` — no usable index (flag off, never indexed, index failed);
 *                 anything present came from the ripgrep best-effort path.
 */
export const BlastStatus = z.enum(['ready', 'partial', 'degraded']);
export type BlastStatus = z.infer<typeof BlastStatus>;

/** One HTTP route, split out of the index's flat `"METHOD /path"` fact. */
export const BlastEndpoint = z.object({
  method: z.string(),
  path: z.string(),
  /** The file that registers the route — where to look, not where it is served. */
  file: z.string(),
});
export type BlastEndpoint = z.infer<typeof BlastEndpoint>;

/** A cross-file reference to a changed symbol. */
export const BlastCallerRef = z.object({
  file: z.string(),
  line: z.number().int(),
  /** Enclosing symbol at that line, or the file's basename when none encloses it. */
  symbol: z.string(),
  /** `file_rank.rank` of the caller file — the sort key, 0 on the degraded path. */
  rank: z.number(),
});
export type BlastCallerRef = z.infer<typeof BlastCallerRef>;

/**
 * One symbol declared in a changed file, with everything reachable from it.
 *
 * `callers` is capped (MAX_CALLERS_PER_SYMBOL) and sorted by `rank` DESC;
 * `caller_count` is the total BEFORE that cap, so the UI can say "20 of 63"
 * instead of quietly showing a truncated list as if it were the whole story.
 */
/**
 * `added` — declared at the PR head but not at the indexed revision.
 * `modified` — pre-existed; the diff touches it.
 *
 * A refactor touches dozens of symbols, so the flat count is dominated by call
 * sites that only shifted a line. This is what separates the handful of things
 * the PR is ABOUT from everything it brushes against.
 */
export const BlastChangeKind = z.enum(['added', 'modified']);
export type BlastChangeKind = z.infer<typeof BlastChangeKind>;

export const BlastSymbol = z.object({
  name: z.string(),
  kind: z.string(),
  file: z.string(),
  change: BlastChangeKind,
  callers: z.array(BlastCallerRef),
  caller_count: z.number().int(),
  endpoints: z.array(BlastEndpoint),
  crons: z.array(z.string()),
});
export type BlastSymbol = z.infer<typeof BlastSymbol>;

/** An earlier PR in the same repo that touched at least one of the same files. */
export const BlastPriorPr = z.object({
  id: z.string(),
  number: z.number().int(),
  title: z.string(),
  author: z.string().nullable(),
  updated_at: z.string().nullable(),
  overlapping_files: z.number().int(),
});
export type BlastPriorPr = z.infer<typeof BlastPriorPr>;

/**
 * `GET /pulls/:id/blast`.
 *
 * NOTE: no field carries a Zod `.default()`. This doubles as the route's
 * response schema, and a default there rewrites what actually goes on the wire
 * (see server/insights.md).
 */
export const BlastRadiusResult = z.object({
  pull_id: z.string(),
  status: BlastStatus,
  /** Human-readable "why not ready", null when `status === 'ready'`. */
  reason: z.string().nullable(),
  /** Mirrors `status === 'degraded'`. The MCP tool keys off this flag. */
  degraded: z.boolean(),
  /**
   * The commit the index was built from — the revision every `file:line` below
   * refers to. Consumers MUST pin code links to this sha rather than to the
   * default branch: callers mostly live outside the diff, and the index can lag
   * `main` by any number of commits, so a branch link silently drifts off by
   * however many lines have been inserted above since. Null when unindexed.
   */
  indexed_sha: z.string().nullable(),
  changed_files: z.array(z.string()),
  symbols: z.array(BlastSymbol),
  /** Flat union of every symbol's endpoints, deduped. */
  endpoints: z.array(BlastEndpoint),
  crons: z.array(z.string()),
  totals: z.object({
    symbols: z.number().int(),
    /** Of `symbols`, how many are new in this PR. */
    added: z.number().int(),
    callers: z.number().int(),
    endpoints: z.number().int(),
    crons: z.number().int(),
  }),
  prior_prs: z.array(BlastPriorPr),
  summary: z.string(),
});
export type BlastRadiusResult = z.infer<typeof BlastRadiusResult>;
